"use client";

import React from "react";
import Image from "next/image";
import { useLanguage } from "../i18n/LanguageContext";

// Dithered, transparent PNGs generated by scripts/illustrations/treat.py
const arts = {
  icarus: { src: "/images/myth/icarus.png", width: 1100, height: 1108 },
  daedalus: { src: "/images/myth/daedalus.png", width: 900, height: 1090 },
  forge: { src: "/images/myth/forge.png", width: 1400, height: 1016 },
  apollo: { src: "/images/myth/apollo.png", width: 900, height: 1166 },
} as const;

export type ArtName = keyof typeof arts;

// A zoomed-in "window" onto part of the same illustration; `at` is a CSS background-position
type Fragment = { className: string; at: string; zoom?: string };

type MythArtProps = {
  art: ArtName;
  className?: string;
  fragments?: Fragment[];
  cover?: boolean;
  priority?: boolean;
  sizes?: string;
};

export default function MythArt({ art, className = "", fragments = [], cover = false, priority = false, sizes = "(max-width: 900px) 100vw, 50vw" }: MythArtProps) {
  const { t } = useLanguage();
  const asset = arts[art];

  return (
    <div className={`myth-art ${cover ? "myth-art-cover" : ""} ${className}`}>
      <div className="myth-art-image">
        {cover ? (
          <Image src={asset.src} alt={t.myth.art[art]} fill sizes={sizes} unoptimized preload={priority} />
        ) : (
          <Image src={asset.src} alt={t.myth.art[art]} width={asset.width} height={asset.height} sizes={sizes} unoptimized preload={priority} />
        )}
      </div>
      {fragments.map((fragment, index) => (
        <div className={`myth-frag ${fragment.className}`} key={fragment.className} aria-hidden="true">
          <span className="myth-frag-bar"><i /><i /><i /><em>FRAG.0{index + 1}</em></span>
          <span className="myth-frag-view" style={{ backgroundImage: `url(${asset.src})`, backgroundPosition: fragment.at, backgroundSize: fragment.zoom ?? "300% auto" }} />
        </div>
      ))}
    </div>
  );
}
